### Elasticsearch Version

8.14

### Installed Plugins

_No response_

### Java Version

_bundled_

### OS Version

any

### Problem Description

While we can index and search via knn with a hexadecimal string when vectors are indexed via bytes, we cannot use script score. 

### Steps to Reproduce

```
DELETE byte_vectors

PUT byte_vectors
{
  "mappings": {
    "properties": {
      "vector": {
        "type": "dense_vector",
        "index": false,
        "element_type": "byte",
        "dims": 128
      }
    }
  }
}


POST byte_vectors/_doc?error_trace
{
  "vector": "09b4cff26acbb50f95699acdef921bcf0c5f7daadf7908f546ae4a948e8850d4d6e654eb56e9d1aac6c88586dc97a4934d160d5dd77103dec17ff7ee021a8997d3bfc4801648e361977a5b248c144dd67ce33450e172bab2d76eac8378d5b93d7d1178d956cc6b2874cfc068821d89ad6e7a0421c478c8e7cff5295f37aae4cd"
}

POST byte_vectors/_search?error_trace
{
  "query": {
    "script_score": {
      "script": {
        "source": "(24 - hamming(params.queryVector, 'vector')) / 24",
        "params": {
          "queryVector": "09b4cff26acbb50f95699acdef921bcf0c5f7daadf7908f546ae4a948e8850d4d6e654eb56e9d1aac6c88586dc97a4934d160d5dd77103dec17ff7ee021a8997d3bfc4801648e361977a5b248c144dd67ce33450e172bab2d76eac8378d5b93d7d1178d956cc6b2874cfc068821d89ad6e7a0421c478c8e7cff5295f37aae4cd"
        }
      },
      "query": {"match_all": {}}
    }
  }
}
```

